export interface Point {
  x: number;
  y: number;
}

export type Direction = 'UP' | 'DOWN' | 'LEFT' | 'RIGHT';

export type GameStatus = 'IDLE' | 'PLAYING' | 'PAUSED' | 'GAME_OVER';

export type GameDifficulty = 'EASY' | 'NORMAL' | 'HARD';

export interface DifficultyConfig {
  intervalMs: number;
  scoreMultiplier: number;
  specialFoodChance: number;
}

export interface FoodItem {
  x: number;
  y: number;
  type: 'NORMAL' | 'SPECIAL';
}

export interface ScoreBoardProps {
  score?: number;
  highScore?: number;
  foodCount?: number;
  difficulty?: GameDifficulty;
  onChangeDifficulty: (diff: GameDifficulty) => void;
  status?: GameStatus;
}

export interface GameBoardProps {
  snake?: Point[];
  food?: FoodItem;
  boardSize?: number;
  status?: GameStatus;
  onRestart: () => void;
  onStart: () => void;
}

export interface ControllerProps {
  onDirectionChange: (dir: Direction) => void;
  onTogglePause: () => void;
  onRestart: () => void;
  status?: GameStatus;
}

import { ScoreBoardProps, GameDifficulty } from '../types';

const DIFFICULTY_LABELS: Record<GameDifficulty, string> = {
  EASY: 'かんたん',
  NORMAL: 'ふつう',
  HARD: 'むずかしい',
};

const ScoreBoard = ({
  score = 0,
  highScore = 0,
  foodCount = 0,
  difficulty = 'NORMAL',
  onChangeDifficulty,
  status = 'IDLE',
}: ScoreBoardProps) => {
  const isPlaying = status === 'PLAYING';

  return (
    <>
      <div className="score-board" aria-label="スコアボード">
        <div className="score-item" aria-live="polite">
          <span className="score-label">スコア</span>
          <span className="score-value">{score}</span>
        </div>
        <div className="score-item">
          <span className="score-label">ハイスコア</span>
          <span className="score-value">{highScore}</span>
        </div>
        <div className="score-item">
          <span className="score-label">食べた数</span>
          <span className="score-value">{foodCount}</span>
        </div>
      </div>

      <div className="difficulty-selector" role="group" aria-label="難易度選択">
        {(['EASY', 'NORMAL', 'HARD'] as GameDifficulty[]).map((diff) => {
          const isActive = difficulty === diff;
          return (
            <button
              key={diff}
              type="button"
              className={`difficulty-btn ${isActive ? 'difficulty-btn-active' : ''}`}
              disabled={isPlaying}
              aria-pressed={isActive}
              onClick={() => onChangeDifficulty?.(diff)}
            >
              {DIFFICULTY_LABELS[diff]}
            </button>
          );
        })}
      </div>
    </>
  );
};

export default ScoreBoard;

import { useMemo } from 'react';
import { GameBoardProps, Point } from '../types';

const GameBoard = ({
  snake = [],
  food = { x: 5, y: 5, type: 'NORMAL' },
  boardSize = 20,
  status = 'IDLE',
  onRestart,
  onStart,
}: GameBoardProps) => {
  const snakeHead = snake[0] || { x: 0, y: 0 };

  const snakeBodySet = useMemo(() => {
    const set = new Set<string>();
    for (let i = 1; i < snake.length; i++) {
      set.add(`${snake[i].x},${snake[i].y}`);
    }
    return set;
  }, [snake]);

  const cells = useMemo(() => {
    const grid: Point[] = [];
    for (let y = 0; y < boardSize; y++) {
      for (let x = 0; x < boardSize; x++) {
        grid.push({ x, y });
      }
    }
    return grid;
  }, [boardSize]);

  return (
    <div className="board-container" role="grid" aria-label="スネークゲーム盤面">
      <div
        className="board-grid"
        style={{
          gridTemplateColumns: `repeat(${boardSize}, 1fr)`,
          gridTemplateRows: `repeat(${boardSize}, 1fr)`,
        }}
      >
        {cells.map(({ x, y }) => {
          const key = `${x},${y}`;
          const isHead = snakeHead.x === x && snakeHead.y === y;
          const isBody = snakeBodySet.has(key);
          const isFood = food.x === x && food.y === y;

          let cellClass = 'board-cell';
          let cellLabel: string | undefined;

          if (isHead) {
            cellClass = 'board-cell cell-snake-head';
            cellLabel = 'ヘビの頭';
          } else if (isBody) {
            cellClass = 'board-cell cell-snake-body';
            cellLabel = 'ヘビの体';
          } else if (isFood) {
            cellClass =
              food.type === 'SPECIAL'
                ? 'board-cell cell-special-food'
                : 'board-cell cell-food';
            cellLabel = food.type === 'SPECIAL' ? 'スペシャルエサ' : 'エサ';
          }

          return (
            <div
              key={key}
              role="gridcell"
              aria-label={cellLabel}
              className={cellClass}
            />
          );
        })}
      </div>

      {status === 'IDLE' && (
        <div className="board-overlay">
          <div className="overlay-title">スネークゲーム</div>
          <div className="overlay-score">エサを食べてヘビを育てよう！</div>
          <button
            type="button"
            className="overlay-btn"
            autoFocus
            onClick={() => onStart?.()}
          >
            ゲーム開始
          </button>
        </div>
      )}

      {status === 'PAUSED' && (
        <div className="board-overlay">
          <div className="overlay-title">一時停止中</div>
          <div className="overlay-score">休憩中... 準備ができたら再開してね</div>
          <button
            type="button"
            className="overlay-btn"
            autoFocus
            onClick={() => onStart?.()}
          >
            ゲーム再開
          </button>
        </div>
      )}

      {status === 'GAME_OVER' && (
        <div className="board-overlay">
          <div className="overlay-title">ゲームオーバー</div>
          <div className="overlay-score">壁やしっぽにぶつかりました</div>
          <button
            type="button"
            className="overlay-btn"
            autoFocus
            onClick={() => onRestart?.()}
          >
            もう一度遊ぶ
          </button>
        </div>
      )}
    </div>
  );
};

export default GameBoard;

import React from 'react';
import { ControllerProps, Direction } from '../types';

const Controller = ({
  onDirectionChange,
  onTogglePause,
  onRestart,
  status = 'IDLE',
}: ControllerProps) => {
  const handlePointerDown = (e: React.PointerEvent<HTMLButtonElement>, dir: Direction) => {
    e.preventDefault();
    onDirectionChange?.(dir);
  };

  const isPaused = status === 'PAUSED';
  const isPlaying = status === 'PLAYING';
  const isGameOver = status === 'GAME_OVER';

  return (
    <div className="controller-container">
      <div className="d-pad" role="group" aria-label="方向コントローラー">
        <button
          type="button"
          aria-label="上へ移動"
          className="d-pad-btn d-pad-up"
          onPointerDown={(e) => handlePointerDown(e, 'UP')}
          onClick={() => onDirectionChange?.('UP')}
        >
          ▲
        </button>
        <button
          type="button"
          aria-label="左へ移動"
          className="d-pad-btn d-pad-left"
          onPointerDown={(e) => handlePointerDown(e, 'LEFT')}
          onClick={() => onDirectionChange?.('LEFT')}
        >
          ◀
        </button>
        <div className="d-pad-center" />
        <button
          type="button"
          aria-label="右へ移動"
          className="d-pad-btn d-pad-right"
          onPointerDown={(e) => handlePointerDown(e, 'RIGHT')}
          onClick={() => onDirectionChange?.('RIGHT')}
        >
          ▶
        </button>
        <button
          type="button"
          aria-label="下へ移動"
          className="d-pad-btn d-pad-down"
          onPointerDown={(e) => handlePointerDown(e, 'DOWN')}
          onClick={() => onDirectionChange?.('DOWN')}
        >
          ▼
        </button>
      </div>

      <div className="control-actions">
        <button
          type="button"
          className="action-btn"
          onClick={() => onTogglePause?.()}
          disabled={isGameOver}
          aria-disabled={isGameOver}
        >
          {isPlaying ? '⏸ 一時停止' : isPaused ? '▶ 再開' : '▶ スタート'}
        </button>
        <button
          type="button"
          className="action-btn"
          onClick={() => onRestart?.()}
        >
          🔄 リセット
        </button>
      </div>

      <div className="instructions-panel">
        PCではキーボードの矢印キーまたはWASDでも操作できます。Spaceキーで一時停止/再開が可能です。
      </div>
    </div>
  );
};

export default Controller;
